document.addEventListener('DOMContentLoaded', function() {
    const roomImages = {
        fachada: "images/fachada.webp",
        habitacion: "images/habitacion.png",
        comedor: "images/comedor.webp",
        cocina: "images/cocina.webp",
        sala: "images/sala.png",
        bano: "images/bano.png"
    };

    const colorPalettes = {
        zafiro: [
            {name: "Zafiro Profundo", class: "color-zafiro-1"},
            {name: "Zafiro Real", class: "color-zafiro-2"},
            {name: "Zafiro Brillante", class: "color-zafiro-3"},
            {name: "Azul Cielo", class: "color-zafiro-4"},
            {name: "Azul Suave", class: "color-zafiro-5"},
            {name: "Azul Claro", class: "color-zafiro-6"},
            {name: "Azul Pastel", class: "color-zafiro-7"},
            {name: "Azul Nube", class: "color-zafiro-8"}
        ],
        dorada: [
            {name: "Oro Oscuro", class: "color-dorada-1"},
            {name: "Oro Antiguo", class: "color-dorada-2"},
            {name: "Oro Clásico", class: "color-dorada-3"},
            {name: "Oro Brillante", class: "color-dorada-4"},
            {name: "Oro Amarillo", class: "color-dorada-5"},
            {name: "Oro Limón", class: "color-dorada-6"},
            {name: "Oro Pálido", class: "color-dorada-7"},
            {name: "Oro Crema", class: "color-dorada-8"}
        ],
        onix: [
            {name: "Ónix Negro", class: "color-onix-1"},
            {name: "Grafito", class: "color-onix-2"},
            {name: "Pizarra", class: "color-onix-3"},
            {name: "Gris Piedra", class: "color-onix-4"},
            {name: "Gris Medio", class: "color-onix-5"},
            {name: "Gris Plata", class: "color-onix-6"},
            {name: "Gris Perla", class: "color-onix-7"},
            {name: "Gris Nube", class: "color-onix-8"}
        ],
        natura: [
            {name: "Verde Bosque", class: "color-natura-1"},
            {name: "Verde Oliva", class: "color-natura-2"},
            {name: "Verde Manzana", class: "color-natura-3"},
            {name: "Verde Lima", class: "color-natura-4"},
            {name: "Verde Fresco", class: "color-natura-5"},
            {name: "Verde Menta", class: "color-natura-6"},
            {name: "Verde Pastel", class: "color-natura-7"},
            {name: "Verde Suave", class: "color-natura-8"}
        ]
    };

    const roomSelector = document.getElementById("room-selector");
    const paletteSelector = document.getElementById("palette-selector");
    const wall = document.getElementById("wall");
    const roomImage = document.getElementById("room-image");
    const colorPalette = document.getElementById("color-palette");
    
    // Variable para guardar el color seleccionado
    let selectedColor = null;
    let currentPalette = null;

    // Bloquear selector de colores inicialmente
    paletteSelector.disabled = true;

    // Precargar imágenes
    function preloadImages() {
        Object.values(roomImages).forEach(src => {
            const img = new Image();
            img.src = src;
        });
    }

    // Mostrar paleta de colores
    function showColorPalette(palette) {
        if (!palette || !colorPalettes[palette]) {
            colorPalette.style.display = "none";
            return;
        }

        currentPalette = palette;
        const colors = colorPalettes[palette];
        let html = '<h3>Colores disponibles</h3><div class="color-grid">';
        
        colors.forEach(color => {
            html += `<div class="color-swatch ${color.class}" data-color="${color.class}">
                        <span class="color-tooltip">${color.name}</span>
                    </div>`;
        });
        
        html += "</div>";
        colorPalette.innerHTML = html;
        colorPalette.style.display = "block";
        
        // Reaplicar el color seleccionado si existe
        if (selectedColor) {
            wall.style.backgroundColor = selectedColor;
        }
    }

    // Resetear todo al seleccionar "Elige un ambiente"
    function resetAll() {
        roomImage.style.display = "none";
        roomImage.src = "";
        paletteSelector.value = "";
        paletteSelector.disabled = true;
        colorPalette.style.display = "none";
        wall.style.backgroundColor = "";
        selectedColor = null;
        currentPalette = null;
    }

    // Event listeners
    roomSelector.addEventListener("change", function() {
        if (!this.value) {
            resetAll();
            return;
        }

        // Cargar la nueva imagen
        roomImage.onload = function() {
            // Ajustar la imagen después de cargar
            adjustImageSize();
            // Habilitar el selector de colores
            paletteSelector.disabled = false;
            // Reaplicar la paleta si había una seleccionada
            if (currentPalette) {
                showColorPalette(currentPalette);
            }
        };
        
        roomImage.src = roomImages[this.value];
        roomImage.style.display = "block";
    });

    function adjustImageSize() {
        // Asegurar que la imagen no sobrepase el contenedor
         const img = roomImage;
    const wallElement = document.getElementById('wall');

    // Asegurar que la imagen no sobrepase el panel_image
    img.style.maxWidth = '100%';
    img.style.maxHeight = '100%';

    // Ajustar el wall al tamaño de la imagen
    wallElement.style.width = 'auto';
    wallElement.style.height = 'auto';
    }

    paletteSelector.addEventListener("change", function() {
        showColorPalette(this.value);
    });

    colorPalette.addEventListener("click", function(e) {
        const colorSwatch = e.target.closest(".color-swatch");
        if (colorSwatch) {
            selectedColor = window.getComputedStyle(colorSwatch).backgroundColor;
            wall.style.backgroundColor = selectedColor;
        }
    });

    // Validación adicional para asegurar que sin imagen no haya color
    function validateWallColor() {
        if (roomImage.style.display === "none" || !roomImage.src) {
            wall.style.backgroundColor = "";
            selectedColor = null;
        }
    }

    // Ejecutar validación periódicamente
    setInterval(validateWallColor, 100);

    // Inicializar
    preloadImages();
    resetAll();
    
    // Manejar redimensionamiento de la ventana
    window.addEventListener('resize', adjustImageSize);
});